import {useEffect,useState} from 'react';
import {BadgeCheck,BarChart3,ExternalLink,FileCheck2,Inbox,RefreshCw,Star,UsersRound} from 'lucide-react';
import {actOnMarketplaceEnrolment,addMarketplaceQualification,getMarketplaceProfile,listMarketplaceEnrolments,saveMarketplaceProfile,submitMarketplaceProfile} from '../../lib/practiceOperationsApi';
import {Button,FeedbackState,Input,LoadingSkeleton,ProgressBar,StatusChip,Surface,TextArea} from './ui/ExternalUI';

const EMPTY={display_name:'',professional_title:'',profession_code:'',profile_photo_url:'',specialisations:[],experience_years:0,bio:'',languages:[],consultation_modes:['ONLINE'],areas_of_focus:[],public_locations:[],services:[],programmes:[],session_duration:60,public_fee_from:null,accepting_new_clients:false};
const split=value=>value.split(',').map(item=>item.trim()).filter(Boolean);
export function ExternalMarketplace(){const[state,setState]=useState('loading');const[data,setData]=useState(null);const[form,setForm]=useState(EMPTY);const[tab,setTab]=useState('profile');const[message,setMessage]=useState('');const[enrolments,setEnrolments]=useState(null);
  const load=()=>{setState('loading');getMarketplaceProfile().then(value=>{setData(value);setForm({...EMPTY,...(value.version?.projection||{})});setState('ready')}).catch(error=>{setMessage(error.message);setState('error')})};useEffect(load,[]);
  const save=async()=>{setMessage('');try{const result=await saveMarketplaceProfile(form);setMessage(`Draft version ${result.version} saved.`);await load()}catch(error){setMessage(error.message)}};
  const submit=async()=>{setMessage('');try{await submitMarketplaceProfile();setMessage('Submitted for Super Admin review. Approval will not publish the profile.');await load()}catch(error){setMessage(error.message)}};
  const showEnrolments=async()=>{setTab('enrolments');if(!enrolments)try{setEnrolments(await listMarketplaceEnrolments())}catch(error){setMessage(error.message)}};
  if(state==='loading')return <LoadingSkeleton height="32rem" label="Loading marketplace profile"/>;if(state==='error')return <FeedbackState kind="error" title="Marketplace profile unavailable" copy={`${message}. No zero metrics are inferred.`} action={<Button icon={RefreshCw} onClick={load}>Retry</Button>}/>;
  const profile=data.profile;const version=data.version;const analytics=data.analytics;return <div className="space-y-5"><header className="flex flex-col justify-between gap-4 rounded-3xl bg-slate-950 p-6 text-white sm:flex-row sm:items-center"><div><p className="text-xs font-bold uppercase tracking-widest text-cyan-300">Consultant marketplace</p><h2 className="mt-2 text-3xl font-bold">Public profile</h2><p className="mt-2 text-sm text-slate-300">Private draft → review → approval → explicit publication. Approved does not mean published.</p></div><StatusChip tone={profile?.status==='PUBLISHED'?'success':'info'}>{profile?.status?.replaceAll('_',' ')||'DRAFT'}</StatusChip></header>
    <nav aria-label="Marketplace workspace" className="flex gap-2 overflow-x-auto">{[['profile','Public Profile'],['qualifications','Qualifications'],['enrolments','Enrolments'],['reviews','Reviews & Analytics']].map(([id,label])=><button key={id} onClick={()=>id==='enrolments'?showEnrolments():setTab(id)} className={`min-h-11 shrink-0 rounded-xl px-4 text-sm font-bold ${tab===id?'bg-blue-700 text-white':'border bg-white'}`}>{label}</button>)}</nav>{message&&<p role="status" className="rounded-xl bg-blue-50 p-3 text-sm text-blue-900">{message}</p>}
    {tab==='profile'&&<div className="grid gap-5 xl:grid-cols-[1fr_320px]"><Surface><h3 className="text-xl font-bold">Profile draft</h3><div className="mt-5 grid gap-4 sm:grid-cols-2"><Field label="Display name"><Input value={form.display_name} onChange={e=>setForm({...form,display_name:e.target.value})}/></Field><Field label="Professional title"><Input value={form.professional_title} onChange={e=>setForm({...form,professional_title:e.target.value})}/></Field><Field label="Profession code"><Input value={form.profession_code} onChange={e=>setForm({...form,profession_code:e.target.value.toUpperCase()})}/></Field><Field label="Experience years"><Input type="number" min="0" value={form.experience_years} onChange={e=>setForm({...form,experience_years:Number(e.target.value)})}/></Field><Field label="Specialisations"><Input value={form.specialisations.join(', ')} onChange={e=>setForm({...form,specialisations:split(e.target.value)})}/></Field><Field label="Languages"><Input value={form.languages.join(', ')} onChange={e=>setForm({...form,languages:split(e.target.value)})}/></Field><Field label="Consultation modes"><Input value={form.consultation_modes.join(', ')} onChange={e=>setForm({...form,consultation_modes:split(e.target.value).map(v=>v.toUpperCase())})}/></Field><Field label="Public services"><Input value={form.services.map(service=>service.name).join(', ')} onChange={e=>setForm({...form,services:split(e.target.value).map(name=>({name,enrolment_mode:'REQUEST_ENROLMENT',active:true}))})}/></Field><Field label="Profile photo approved derivative"><Input value={form.profile_photo_url||''} onChange={e=>setForm({...form,profile_photo_url:e.target.value})}/></Field><Field wide label="Bio"><TextArea rows="6" value={form.bio} onChange={e=>setForm({...form,bio:e.target.value})}/></Field><Field label="Areas of focus"><Input value={form.areas_of_focus.join(', ')} onChange={e=>setForm({...form,areas_of_focus:split(e.target.value)})}/></Field><Field label="Fee from (minor units)"><Input type="number" min="0" value={form.public_fee_from??''} onChange={e=>setForm({...form,public_fee_from:e.target.value===''?null:Number(e.target.value)})}/></Field><label className="flex min-h-12 items-center gap-3 rounded-xl border p-3 text-sm font-bold"><input type="checkbox" checked={form.accepting_new_clients} onChange={e=>setForm({...form,accepting_new_clients:e.target.checked})}/>Accepting new clients</label></div><div className="mt-6 flex flex-wrap gap-3"><Button variant="primary" onClick={save}>Save draft</Button><Button onClick={submit} disabled={!version||version.completeness<100||['SUBMITTED_FOR_REVIEW','UNDER_REVIEW'].includes(profile?.status)}>Submit for review</Button>{profile?.slug&&<a className="inline-flex min-h-11 items-center gap-2 rounded-xl border px-4 text-sm font-bold" href={`/consultants/${profile.slug}`} target="_blank" rel="noreferrer">Preview <ExternalLink size={16}/></a>}</div></Surface><Surface><h3 className="font-bold">Profile completeness</h3><div className="mt-4"><ProgressBar value={version?.completeness||0} label="Deterministic completeness"/></div><ul className="mt-4 space-y-2 text-sm">{(version?.missing_fields||[]).map(item=><li key={item} className="rounded-lg bg-amber-50 p-2 text-amber-900">Missing: {item}</li>)}</ul><p className="mt-5 text-xs text-slate-500">Published versions remain immutable. Editing a live profile creates a new draft while the current version stays public.</p></Surface></div>}
    {tab==='qualifications'&&<Qualifications items={data.qualifications||[]} onDone={load} onMessage={setMessage}/>}
    {tab==='enrolments'&&<Surface><h3 className="text-xl font-bold">New enrolment requests</h3>{enrolments===null?<LoadingSkeleton/>:enrolments.state==='CONFIRMED_EMPTY'?<FeedbackState title="No confirmed enrolment requests" copy="A failed request is never shown as an empty inbox."/>:<div className="mt-4 divide-y">{enrolments.items.map(item=><article key={item.id} className="py-4"><div className="flex flex-wrap items-center justify-between gap-2"><strong>{item.full_name}</strong><StatusChip>{item.status}</StatusChip></div><p className="mt-1 text-sm text-slate-500">{item.consultation_mode||'Mode not selected'} · {item.preferred_at?new Date(item.preferred_at).toLocaleString():'No preferred slot'}</p><div className="mt-3 flex flex-wrap gap-2"><Button size="small" onClick={()=>location.hash='leads'}>Open lead</Button>{[['Contact','CONTACT'],['Accept','ACCEPT'],['Book','BOOK'],['Decline','DECLINE'],['Convert','CONVERT']].map(([label,action])=><Button key={action} size="small" onClick={async()=>{try{await actOnMarketplaceEnrolment(item.id,action);setMessage(`${label} completed.`);setEnrolments(await listMarketplaceEnrolments())}catch(error){setMessage(error.message)}}}>{label}</Button>)}</div></article>)}</div>}</Surface>}
    {tab==='reviews'&&<div className="grid gap-4 sm:grid-cols-2 lg:grid-cols-4">{[[BarChart3,'Profile views',analytics?.profile_views],[UsersRound,'Enrolments',analytics?.enrolments?.total],[Star,'Verified reviews',analytics?.review_count],[BadgeCheck,'Average rating',analytics?.average_rating||'New on Zestiva']].map(([Icon,label,value])=><Surface key={label}><Icon className="text-blue-700"/><p className="mt-4 text-sm text-slate-500">{label}</p><strong className="mt-1 block text-2xl">{value??'—'}</strong></Surface>)}</div>}
  </div>}
function Field({label,wide,children}){return <label className={`text-sm font-bold ${wide?'sm:col-span-2':''}`}>{label}<span className="mt-2 block">{children}</span></label>}
function Qualifications({items,onDone,onMessage}){const[form,setForm]=useState({qualification_type:'DEGREE',title:'',institution:'',award_year:new Date().getFullYear(),country:'',registration_number:'',issuing_body:'',expiry_date:'',credential_document_id:''});const add=async()=>{try{await addMarketplaceQualification({...form,expiry_date:form.expiry_date||null,credential_document_id:form.credential_document_id||null});onMessage('Qualification added for independent verification.');onDone()}catch(error){onMessage(error.message)}};return <div className="grid gap-5 lg:grid-cols-2"><Surface><h3 className="text-xl font-bold">Add qualification</h3><div className="mt-4 space-y-3">{[['title','Degree / title'],['institution','Institution'],['award_year','Year'],['country','Country'],['registration_number','Registration number'],['issuing_body','Issuing body'],['expiry_date','Expiry date'],['credential_document_id','Private vault document ID']].map(([key,label])=><Field key={key} label={label}><Input type={key==='award_year'?'number':key==='expiry_date'?'date':'text'} value={form[key]} onChange={e=>setForm({...form,[key]:key==='award_year'?Number(e.target.value):e.target.value})}/></Field>)}<Button variant="primary" onClick={add}>Add credential</Button></div></Surface><Surface><h3 className="text-xl font-bold">Verification</h3>{items.length?<div className="mt-4 divide-y">{items.map(item=><article className="py-3" key={item.id}><div className="flex justify-between gap-3"><strong>{item.title}</strong><StatusChip tone={item.verification_status==='VERIFIED'?'success':'neutral'}>{item.verification_status}</StatusChip></div><p className="mt-1 text-sm text-slate-500">{item.institution} · {item.award_year}</p><p className="mt-1 text-xs text-slate-400">Evidence remains private in Document Vault.</p></article>)}</div>:<FeedbackState title="No qualifications added" copy="At least one independently verified qualification is required for profile completeness."/>}</Surface></div>}
